-- WoW Forever 1.60.1.70862: resolve 2,095 diagnosed model-less templates.
-- Archive selection: 2,022 unplaced build-69497 NPCs without found incoming DB/client
-- dependencies. Numeric references across src were checked after lexing C++ comments:
-- remaining occurrences are typed spell/model/text/etc. IDs, not NPC references.
-- Classic stats/level records and templates with model rows are protected.
-- Restore 76 model rows for 73 Classic NPCs whose entry AND English name match
-- CMaNGOS ClassicDB_1_12_1_z2815. DisplayIDs exist in local CreatureDisplayInfo.db2,
-- Wago build 70862, and installed creature_model_info. Identity conflicts are retained.
-- Source: https://github.com/cmangos/classic-db/tree/master/Full_DB
-- Guard original identity and absence of models; do not replace subsequently repaired rows.
CREATE TEMPORARY TABLE released_prune (id INT UNSIGNED PRIMARY KEY);
