DELETE b FROM released_prune b JOIN battlemaster_entry m ON m.entry=b.id;
DELETE b FROM released_prune b JOIN npc_vendor v ON -v.item=b.id WHERE v.item<0;
DELETE b FROM released_prune b JOIN creature c ON c.id=b.id;
DELETE b FROM released_prune b JOIN creature_template c ON c.entry=b.id WHERE c.StringId IS NOT NULL AND c.StringId<>'';
START TRANSACTION;
DELETE b FROM released_prune b JOIN creature_template c ON c.entry=b.id WHERE c.VerifiedBuild<>69497 OR EXISTS(SELECT 1 FROM creature p WHERE p.id=b.id) OR EXISTS(SELECT 1 FROM creature_classic_level l WHERE l.entry=b.id) OR EXISTS(SELECT 1 FROM creature_classic_stats l WHERE l.entry=b.id) OR EXISTS(SELECT 1 FROM creature_template_model m WHERE m.CreatureID=b.id);

DELETE d FROM smart_scripts d JOIN released_prune b ON b.id=d.entryorguid WHERE d.source_type=0;
DELETE d FROM creature_equip_template d JOIN released_prune b ON b.id=d.CreatureID;
DELETE d FROM creature_template_addon d JOIN released_prune b ON b.id=d.entry;
DELETE d FROM creature_template_difficulty d JOIN released_prune b ON b.id=d.Entry;
DELETE d FROM creature_template_locale d JOIN released_prune b ON b.id=d.entry;
DELETE d FROM creature_template_model d JOIN released_prune b ON b.id=d.CreatureID;
