DELETE d FROM creature_template_resistance d JOIN released_prune b ON b.id=d.CreatureID;
DELETE d FROM creature_template_sparring d JOIN released_prune b ON b.id=d.Entry;
DELETE d FROM creature_template_spell d JOIN released_prune b ON b.id=d.CreatureID;
DELETE d FROM creature_template_gossip d JOIN released_prune b ON b.id=d.CreatureID;
DELETE d FROM creature_trainer d JOIN released_prune b ON b.id=d.CreatureID;
DELETE d FROM creature_text_locale d JOIN released_prune b ON b.id=d.CreatureID;
DELETE d FROM creature_text d JOIN released_prune b ON b.id=d.CreatureID;
