DELETE d FROM npc_spellclick_spells d JOIN released_prune b ON b.id=d.npc_entry;
DELETE d FROM creature_questitem d JOIN released_prune b ON b.id=d.CreatureEntry;
DELETE d FROM creature_quest_currency d JOIN released_prune b ON b.id=d.CreatureId;
DELETE d FROM creature_onkill_reputation d JOIN released_prune b ON b.id=d.creature_id;
DELETE d FROM quest_greeting_locale d JOIN released_prune b ON b.id=d.ID WHERE 1=1 AND d.type=0;
